package protoc_test

import (
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/wham/protoc-go/protoc"
	pluginpb "google.golang.org/protobuf/types/pluginpb"
)

// benchCase is one input fed to the compiler-core benchmarks. dir holds the
// .proto files; the case is skipped if dir does not exist so the scaled tiers
// (generated by scripts/gen-large-stress into testdata/bench/) are optional.
// glob selects the sources within dir and defaults to "*.proto"; a case whose
// sources live in a tree (the vendored upstream corpus) sets it explicitly.
type benchCase struct {
	name string
	dir  string
	glob string
	// needsProtocInclude marks a case that imports .proto files shipped only in
	// the C++ protoc include directory, not embedded in protoc-go and not
	// vendored here. Without that directory the case is skipped rather than
	// benchmarked on a subset, so the numbers always describe the same work.
	needsProtocInclude bool
}

var benchCases = []benchCase{
	{name: "01_basic", dir: "../testdata/01_basic_message"},
	{name: "bench_tiny", dir: "../testdata/bench/tiny"},
	{name: "bench_small", dir: "../testdata/bench/small"},
	{name: "bench_medium", dir: "../testdata/bench/medium"},
	{name: "bench_large", dir: "../testdata/bench/large"},
	{name: "329_large_stress", dir: "../testdata/329_large_stress"},
	// The upstream protobuf test corpus, compiled in one pass: 53 real .proto
	// files with imports, custom options, extensions and editions, written by
	// the protobuf maintainers rather than by this project's generator. It is
	// the only case here shaped like a real project.
	{
		name:               "google_corpus",
		dir:                "../testdata/google",
		glob:               "google/protobuf/*.proto",
		needsProtocInclude: true,
	},
}

// protoIncludeDirs lists the usual homes of the C++ protoc include directory,
// in the same order scripts/bench probes them.
var protoIncludeDirs = []string{
	"/opt/homebrew/include",
	"/usr/local/include",
	"/tmp/protoc-install/include",
	"/usr/include",
}

func protocInclude() string {
	for _, d := range protoIncludeDirs {
		if fi, err := os.Stat(filepath.Join(d, "google", "protobuf")); err == nil && fi.IsDir() {
			return d
		}
	}
	return ""
}

// benchInputs resolves a case into the source names to compile and the proto
// paths to resolve them against. ok is false when the case cannot be run as
// specified, with why saying so.
func benchInputs(bc benchCase) (sources, paths []string, why string, ok bool) {
	glob := bc.glob
	if glob == "" {
		glob = "*.proto"
	}
	matches, err := filepath.Glob(filepath.Join(bc.dir, glob))
	if err != nil || len(matches) == 0 {
		return nil, nil, fmt.Sprintf("corpus %s missing (run: scripts/gen-large-stress %s)", bc.dir, bc.name), false
	}
	sources = make([]string, len(matches))
	for i, m := range matches {
		rel, err := filepath.Rel(bc.dir, m)
		if err != nil {
			return nil, nil, fmt.Sprintf("%s: %v", m, err), false
		}
		sources[i] = filepath.ToSlash(rel)
	}
	paths = []string{bc.dir}
	if bc.needsProtocInclude {
		inc := protocInclude()
		if inc == "" {
			return nil, nil, "C++ protoc include directory not found (run .github/install-target-protoc.sh)", false
		}
		paths = append(paths, inc)
	}
	return sources, paths, "", true
}

// BenchmarkCompile measures the compiler core (parse → link → build
// descriptors) in-process, with zero process-startup noise. This is the
// co-implementation's throughput ceiling; compare it against the C++ CLI
// number from scripts/bench minus the startup baseline.
func BenchmarkCompile(b *testing.B) {
	for _, bc := range benchCases {
		files, paths, why, ok := benchInputs(bc)
		if !ok {
			b.Run(bc.name, func(b *testing.B) { b.Skip(why) })
			continue
		}
		c := protoc.New(protoc.WithProtoPaths(paths...))
		b.Run(bc.name, func(b *testing.B) {
			b.ReportAllocs()
			for i := 0; i < b.N; i++ {
				if _, err := c.Compile(files...); err != nil {
					b.Fatalf("compile failed: %v", err)
				}
			}
		})
	}
}

// BenchmarkCompileSourceInfo measures the same compile with SourceCodeInfo
// retained — the dominant extra cost when generating debuggable descriptors.
func BenchmarkCompileSourceInfo(b *testing.B) {
	for _, bc := range benchCases {
		files, paths, why, ok := benchInputs(bc)
		if !ok {
			b.Run(bc.name, func(b *testing.B) { b.Skip(why) })
			continue
		}
		c := protoc.New(
			protoc.WithProtoPaths(paths...),
			protoc.WithIncludeSourceInfo(),
		)
		b.Run(bc.name, func(b *testing.B) {
			b.ReportAllocs()
			for i := 0; i < b.N; i++ {
				if _, err := c.Compile(files...); err != nil {
					b.Fatalf("compile failed: %v", err)
				}
			}
		})
	}
}

// nopPlugin is a trivial in-process plugin that produces no files. It isolates
// plugin-dispatch overhead (request building + invocation) from generation.
type nopPlugin struct{}

func (nopPlugin) Generate(*pluginpb.CodeGeneratorRequest) (*pluginpb.CodeGeneratorResponse, error) {
	return &pluginpb.CodeGeneratorResponse{}, nil
}

// BenchmarkPluginDispatch quantifies the in-process plugin advantage the README
// claims. The "library" sub-benchmark calls a plugin directly; the "subprocess"
// sub-benchmark forks protoc-gen-dump over stdin/stdout. The subprocess variant
// is skipped unless the plugin binary has been built (scripts/test builds it).
//
// A tiny input is used on purpose: it keeps the plugin's own work negligible so
// the measured gap reflects dispatch overhead (request marshal + fork/exec +
// pipe round-trip) rather than how much the plugin generates.
func BenchmarkPluginDispatch(b *testing.B) {
	const dir = "../testdata/01_basic_message"
	files, paths, why, ok := benchInputs(benchCase{name: "01_basic", dir: dir})
	if !ok {
		b.Skip(why)
	}
	result, err := protoc.New(protoc.WithProtoPaths(paths...)).Compile(files...)
	if err != nil {
		b.Fatalf("compile failed: %v", err)
	}

	b.Run("library", func(b *testing.B) {
		b.ReportAllocs()
		p := nopPlugin{}
		for i := 0; i < b.N; i++ {
			if _, err := result.RunLibraryPlugin(p, ""); err != nil {
				b.Fatalf("library plugin failed: %v", err)
			}
		}
	})

	pluginBin := "../tools/protoc-gen-dump/protoc-gen-dump"
	b.Run("subprocess", func(b *testing.B) {
		if _, err := os.Stat(pluginBin); err != nil {
			b.Skipf("plugin binary not built: %s (run: scripts/test)", pluginBin)
		}
		// protoc-gen-dump writes to the directory named by its parameter.
		outDir := b.TempDir()
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			if _, err := result.RunPlugin(pluginBin, outDir); err != nil {
				b.Fatalf("subprocess plugin failed: %v", err)
			}
		}
	})
}
